static inline int ceil_div_int(int a, int b) { return (a + b - 1) / b; }

__device__ __forceinline__ float warp_reduce_max_bcast(float v) {
    unsigned mask = 0xffffffffu;
    v = fmaxf(v, __shfl_down_sync(mask, v, 16));
    v = fmaxf(v, __shfl_down_sync(mask, v, 8));
    v = fmaxf(v, __shfl_down_sync(mask, v, 4));
    v = fmaxf(v, __shfl_down_sync(mask, v, 2));
    v = fmaxf(v, __shfl_down_sync(mask, v, 1));
    return __shfl_sync(mask, v, 0);
}

__device__ __forceinline__ float warp_reduce_sum_bcast(float v) {
    unsigned mask = 0xffffffffu;
    v += __shfl_down_sync(mask, v, 16);
    v += __shfl_down_sync(mask, v, 8);
    v += __shfl_down_sync(mask, v, 4);
    v += __shfl_down_sync(mask, v, 2);
    v += __shfl_down_sync(mask, v, 1);
    return __shfl_sync(mask, v, 0);
}

template<int BLOCK_THREADS>
__device__ __forceinline__ float block_reduce_max_bcast(float v) {
    __shared__ float smem[32];
    int lane = threadIdx.x & 31;
    int wid = threadIdx.x >> 5;
    unsigned mask = 0xffffffffu;
    v = fmaxf(v, __shfl_down_sync(mask, v, 16));
    v = fmaxf(v, __shfl_down_sync(mask, v, 8));
    v = fmaxf(v, __shfl_down_sync(mask, v, 4));
    v = fmaxf(v, __shfl_down_sync(mask, v, 2));
    v = fmaxf(v, __shfl_down_sync(mask, v, 1));
    if (lane == 0) smem[wid] = v;
    __syncthreads();
    if (threadIdx.x < 32) {
        float x = (lane < (BLOCK_THREADS + 31) / 32) ? smem[lane] : -CUDART_INF_F;
        x = fmaxf(x, __shfl_down_sync(mask, x, 16));
        x = fmaxf(x, __shfl_down_sync(mask, x, 8));
        x = fmaxf(x, __shfl_down_sync(mask, x, 4));
        x = fmaxf(x, __shfl_down_sync(mask, x, 2));
        x = fmaxf(x, __shfl_down_sync(mask, x, 1));
        if (threadIdx.x == 0) smem[0] = x;
    }
    __syncthreads();
    return smem[0];
}

template<int BLOCK_THREADS>
__device__ __forceinline__ float block_reduce_sum_bcast(float v) {
    __shared__ float smem[32];
