            m = fmaxf(m, (float)row_in[col]);
        }
        m = block_reduce_max_bcast<BLOCK_THREADS>(m);
        float s = 0.f;
        for (int col = tid; col < n_cols; col += BLOCK_THREADS) {
            s += __expf((float)row_in[col] - m);
