                                    long in_stride, long out_stride, int n_rows, int n_cols) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp = tid >> 5;
    int row = blockIdx.x * WARPS_PER_BLOCK + warp;
    int row_step = gridDim.x * WARPS_PER_BLOCK;
    for (; row < n_rows; row += row_step) {
        const scalar_t* row_in = in + (long)row * in_stride;
        scalar_t* row_out = out + (long)row * out_stride;
        float vals[ITEMS];
        float m = -CUDART_INF_F;
        #pragma unroll
        for (int i = 0; i < ITEMS; ++i) {
            int col = lane + i * 32;
            float v = (col < n_cols) ? (float)row_in[col] : -CUDART_INF_F;
            vals[i] = v;
            m = fmaxf(m, v);
        }
        m = warp_reduce_max_bcast(m);
        float s = 0.f;
        #pragma unroll
        for (int i = 0; i < ITEMS; ++i) {
            int col = lane + i * 32;
            float e = (col < n_cols) ? __expf(vals[i] - m) : 0.f;
            vals[i] = e;
            s += e;
        }
        s = warp_reduce_sum_bcast(s);
        float inv = 1.0f / s;
        #pragma unroll
        for (int i = 0; i < ITEMS; ++i) {
            int col = lane + i * 32;
            if (col < n_cols) row_out[col] = (scalar_t)(vals[i] * inv);
        }
    }
}

template <typename scalar_t, int BLOCK_THREADS, int ITEMS>
__global__ void softmax_block_kernel(scalar_t* __restrict__ out, const scalar_t* __restrict__ in,
                                     long in_stride, long out_stride, int n_rows, int n_cols) {
    int tid = threadIdx.x;
    int row = blockIdx.x;
    int row_step = gridDim.x;
    for (; row < n_rows; row += row_step) {
        const scalar_t* row_in = in + (long)row * in_stride;
        scalar_t* row_out = out + (long)row * out_stride;
        float vals[ITEMS];
        float m = -CUDART_INF_F;
        #pragma unroll
        for (int i = 0; i < ITEMS; ++i) {
            int col = tid + i * BLOCK_THREADS;
            float v = (col < n_cols) ? (float)row_in[col] : -CUDART_INF_F;
            vals[i] = v;
            m = fmaxf(m, v);
        }
        m = block_reduce_max_bcast<BLOCK_THREADS>(m);
        float s = 0.f;
        #pragma unroll
        for (int i = 0; i < ITEMS; ++i) {
            int col = tid + i * BLOCK_THREADS;
            float e = (col < n_cols) ? __expf(vals[i] - m) : 0.f;
            vals[i] = e;
            s += e;
        }
        s = block_reduce_sum_bcast<BLOCK_THREADS>(s);
        float inv = 1.0f / s;
        #pragma unroll
        for (int i = 0; i < ITEMS; ++i) {
            int col = tid + i * BLOCK_THREADS;
            if (col < n_cols) row_out[col] = (scalar_t)(vals[i] * inv);
        }
    }
}

template <typename scalar_t, int BLOCK_THREADS>
__global__ void softmax_large_kernel(scalar_t* __restrict__ out, const scalar_t* __restrict__ in,
                                     long in_stride, long out_stride, int n_rows, int n_cols) {
    int tid = threadIdx.x;
    for (int row = blockIdx.x; row < n_rows; row += gridDim.x) {
        const scalar_t* row_in = in + (long)row * in_stride;
        scalar_t* row_out = out + (long)row * out_stride;
        float m = -CUDART_INF_F;
        for (int col = tid; col < n_cols; col += BLOCK_THREADS) {
            m = fmaxf(m, (float)row_in[col]);
        }
        m = block_reduce_max_bcast<BLOCK_THREADS>(m);
        float s = 0.f;
        for (int col = tid; col < n_cols; col += BLOCK_THREADS) {
            s += __expf((float)row_in[col] - m);
        }
        s = block_reduce_sum_bcast<BLOCK_THREADS>(s);
        float inv = 1.0f / s;
        for (int col = tid; col < n_cols; col += BLOCK_THREADS) {
            row_out[col] = (scalar_t)(__expf((float)row_in[col] - m) * inv);
        }
    }
}

