torch::Tensor softmax_forward(torch::Tensor x) {
    auto y = torch::empty_like(x);
    int N = (int)x.size(0);
    int D = (int)x.size(1);
    if (N == 0 || D == 0) return y;
    long in_stride = (long)x.stride(0);
    long out_stride = (long)y.stride(0);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    int device = x.get_device();
    cudaDeviceProp* prop = at::cuda::getDeviceProperties(device);
    int sm_count = prop->multiProcessorCount;
    AT_DISPATCH_FLOATING_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, x.scalar_type(), "softmax_forward_cuda", [&] {
        using scalar_t_ = scalar_t;
        DISPATCH_KERNELS(scalar_t_);
    });
    return y;
}
